/// A whole object's host: `(the C++ object, op, a, b, c, d, f)` -> the op's result.
using EeUiHostFn = ptrdiff_t(*)(void *obj,
                                EeUiOp op,
                                ptrdiff_t a,
                                ptrdiff_t b,
                                ptrdiff_t c,
                                ptrdiff_t d,
                                float *f);

