/// `CopyData`'s rectangles: the title's, the axis labels' (empty when off) and the plot area.
struct EeUiGraphLayout {
  EeUiRect title;
  EeUiRect y_axis;
  EeUiRect x_axis;
  EeUiRect graph;
};

/// Which texts `CopyData` lays out: each label's flag (`mLabelGraph` ..) and whether its text exists (`SetFont`
/// made them).
struct EeUiGraphTexts {
  bool label_graph;
  bool has_title;
  bool label_grid;
  bool has_grid;
  bool label_y;
  bool has_y;
  bool label_x;
  bool has_x;
};

/// A graph's value range (`UGraph`'s or the displayed one, `UIGraph::mMinX` ..).
struct EeUiGraphRange {
  long min_x;
  long max_x;
  long min_y;
  long max_y;
};

/// What `SetCandidateList` leaves: the window's left and right edges and the selected line within the page.
struct EeUiCandidateFit {
  float left;
  float right;
  long selection;
};

/// One line of the window's border.
struct EeUiCandidateLine {
  float x0;
  float y0;
  float x1;
  float y1;
  /// The light border colour (else the dark one).
  bool light;
};

/// `DrawPolygons`' plan after the background: the selection bar (when `selection` is not negative: the selected
/// line, two pixels in from each side, clipped to the window) and the two-pixel bevelled border, top (dark),
/// bottom (light), left (dark), right (light), in the C++'s order.
struct EeUiCandidateFrame {
  bool has_selection;
  EeUiRect selection;
  EeUiCandidateLine lines[8];
};

/// One line of `UIControl::DrawBorder`: from `start` to `end` in the light colour (`UIControl::sLightBorder`) or the
/// dark one (`sDarkBorder`).
struct EeUiBorderLine {
  EeUiPoint start;
  EeUiPoint end;
  bool light;
};

/// What `UIForm::DrawClippedText` clips against (`clips`: the form's `mClipRectangles`, `clip_count` of them, read
/// before the first draw).
struct EeUiClipInfo {
  const EeUiRect *clips;
  size_t clip_count;
  bool has_popup;
  bool popup_is_control;
  EeUiRect popup_rect;
  EeUiRect popup_draw_rect;
  bool has_candidate;
  EeUiRect candidate_rect;
};

/// The C++'s text draw: `Draw(text, *r, drawing surface)` -> its result.
using EeUiTextDrawFn = long(*)(void *ctx, const EeUiRect *r);

/// `UICheckBox`'s members in their C++ order (from `mTextLabel` on).
struct EeUiCheckFields {
  /// `UITextLabel*`, C++'s.
  void *text_label;
  bool is_checked;
  bool has_text;
  bool scale_bitmap;
  bool is_disabled;
};

/// `UIRadioButton`'s members in their C++ order (from `mOtherNormalBitmap` on).
struct EeUiRadioFields {
  void *other_normal_bitmap;
  void *other_pressed_bitmap;
  /// `UITextLabel*`, C++'s.
  void *text_label;
  bool is_checked;
  bool has_text;
  bool is_push_button;
  bool scale_bitmap;
};

/// `UIScrollBar`'s members in their C++ order (from `mIncrementButton` on). The pointers are C++'s.
struct ScrollBarFields {
  void *increment_button;
  void *decrement_button;
  void *slider;
  bool increment_pressed;
  bool decrement_pressed;
  bool slider_pressed;
};

/// A table's identity as `AddControlLike` and `MoveControlsHorizontally` search the static array.
struct EeUiControlsTableKey {
  long id;
  long form_id;
  long form_index;
};

/// One queued event (`UIEventTrigger`): the referenced event, its form and entity, C++'s.
struct EeUiTrigger {
  void *event;
  void *form;
  void *entity;
};

/// `UIDirtyRectangle`: a rectangle and the surfaces it still has to be redrawn on.
struct EeUiDirtyRect {
  EeUiRect rect;
  unsigned long surface_count;
};

